import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CSVParser_getHeaderMap_TriageGen2Test {

    @Test
    public void testGetHeaderMap_WithHeaders() throws IOException {
        // Arrange: Create a CSV string with a header row
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT.withHeader();

        // Act
        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Assert
            assertNotNull("Header map should not be null when headers are present", headerMap);
            assertEquals("Header map size should match number of columns", 3, headerMap.size());
            assertEquals(Integer.valueOf(0), headerMap.get("id"));
            assertEquals(Integer.valueOf(1), headerMap.get("name"));
            assertEquals(Integer.valueOf(2), headerMap.get("age"));

            // Verify it returns a copy (LinkedHashMap) by modifying the returned map
            headerMap.put("new", 99);
            assertFalse("Modifying returned map should not affect internal state", parser.getHeaderMap().containsKey("new"));
        }
    }

    @Test
    public void testGetHeaderMap_NoHeaders() throws IOException {
        // Arrange: Create a CSV string without a header row
        String csvContent = "1,John,30\n2,Jane,25";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT; // No header defined

        // Act
        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Assert
            // Based on the implementation: return false ? null : new LinkedHashMap<>(this.headerMap);
            // If headerMap is empty, it returns an empty map, not null.
            assertNotNull("Header map should be an empty map, not null, if no headers are defined", headerMap);
            assertTrue("Header map should be empty", headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMap_EmptyContent() throws IOException {
        // Arrange
        String csvContent = "";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT.withHeader("col1", "col2");

        // Act
        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Assert
            assertNotNull(headerMap);
            assertEquals(2, headerMap.size());
            assertEquals(Integer.valueOf(0), headerMap.get("col1"));
        }
    }
}
